function eligible(r,ignoreGeo=false){const associated=window.PoeticsStateMap.statesForRecord(r);return (zone==='All zones'||associated.some(s=>window.PoeticsStateMap.zones[zone].includes(s)))&&(!associated.length||associated.some(s=>enabledStates.has(s)))&& (ignoreGeo||state==='All states'||window.PoeticsStateMap.statesForRecord(r).includes(state))&& (year==='All years'||(year==='Year unverified'?!r.years.length:r.years.some(y=>String(y.year)===year)))&& (activity==='All formats'||r.format===activity)&&enabled.has(r.category)&&(ignoreGeo||geo==='All places'||cityMatch(r,geo))&&(r.name+' '+(r.searchAliases||[]).concat(r.nameVariants||[]).join(' ')+' '+r.summary+' '+r.city).toLowerCase().includes(query.toLowerCase());}
