function relationGroup(r,category){const links=related(r).filter(x=>x.record.category===category);const unique=[...new Set(links.map(x=>x.record.id))];return `<div class="profile-connection-group"><h3>${window.PoeticsIcon(category)}${h(category==='Prizes'?'Prizes & Competitions':category)}<span>${unique.length}</span></h3>${unique.length?unique.map(id=>{const n=rows.find(n=>n.id===id),records=links.filter(x=>x.record.id===id);return `<div class="profile-connection"><button data-node="${h(id)}"><strong>${h(n.name)}</strong><small>${h([...new Set(records.map(x=>x.edge.label))].join(' · '))}</small></button><a href="${h(records[0].edge.url)}" target="_blank" rel="noopener" aria-label="Evidence for connection to ${h(n.name)}">Source</a></div>`;}).join(''):'<p class="profile-missing">No reviewed connection yet.</p>'}</div>`;}
function statusTags(r){const a=r.activityStatus;return `${r.eventEvidence?`<span class="entry-status" data-event-evidence="${h(r.eventEvidence)}">${h(r.eventEvidence)}</span>`:''}<span class="entry-status" data-verification="${h(r.verification.label)}">${h(r.verification.label)}</span>${a?`<span class="entry-status" data-activity-status="${h(a.label)}" title="${h(a.note)}">${h(a.label)}${a.date?' · '+h(a.date):''}</span>`:''}${r.publicationState?`<span class="entry-status">${h(r.publicationState)}</span>`:''}${r.phase?`<span class="entry-status">${h(r.phase.label)} · ${h(r.phase.date)}</span>`:''}`;}
function details(r){return `<article class="atlas-profile">${media(r)}<span class="badge">${window.PoeticsIcon(r.category)}${h(r.category==='Prizes'?'Prize / competition':r.category)}</span><h2>${h(r.name)}</h2><div class="entry-statuses">${statusTags(r)}</div><dl class="profile-facts"><div><dt>Location</dt><dd>${h(r.locationLabel)}</dd></div><div><dt>Documented years</dt><dd>${h(r.yearLabel)}</dd></div>${r.nameVariants?.length?`<div><dt>Also recorded as</dt><dd>${h(r.nameVariants.join(' · '))}</dd></div>`:''}<div><dt>Entry type</dt><dd>${h(r.entryType)}</dd></div><div><dt>Dates and basis</dt><dd>${h(r.dateLabel)}</dd><dd>${h(r.dateBasis)}</dd></div></dl>${r.bibliography?`<details class="profile-years"><summary>Publication metadata</summary><dl class="profile-facts">${Object.entries(r.bibliography).map(([label,value])=>`<div><dt>${h(label)}</dt><dd>${h(value)}</dd></div>`).join('')}</dl></details>`:''}<h3>Details</h3><p>${h(r.details)}</p>${r.history?`<p>${h(r.history)}</p>`:''}<details class="profile-years"><summary>What the years refer to</summary>${r.years.length?r.years.map(y=>`<p><b>${y.year}</b> · ${h(y.label)}${y.url?` <a href="${h(y.url)}" target="_blank" rel="noopener">Evidence </a>`:''}</p>`).join(''):'<p>No reviewed year for this entry.</p>'}<p class="caption">Source and programme years do not establish birth, founding, residence or attendance.</p></details><div class="profile-network-heading"><h3>Connections</h3><button id="show-connections">View network </button></div>${['People','Places','Platforms','Prizes','Publications'].map(c=>relationGroup(r,c)).join('')}<details class="directory-evidence"><summary>Sources & verification · ${r.links.length}</summary><p class="caption">${h(r.status)}</p><p>Review: ${h(r.verification.label)}${r.verification.reviewedAt?' · '+h(r.verification.reviewedAt):''}. ${h(r.verification.scope)}</p>${r.activityStatus?`<p>${h(r.activityStatus.note)}${r.activityStatus.url?` <a href="${h(r.activityStatus.url)}" target="_blank" rel="noopener">Activity evidence </a>`:''}</p>`:''}<p class="caption">${h(r.availability)}</p>${r.gaps?`<p>${h(r.gaps)}</p>`:''}${r.verification.sourceLocator?`<p class="caption">Source location: ${h(r.verification.sourceLocator)}</p>`:''}${r.links.map(l=>`<p><a href="${h(l.url)}" target="_blank" rel="noopener">${h(l.title)} </a></p>`).join('')}${r.pilot?.rights&&!r.media.length?`<p class="caption">${h(r.pilot.rights)}</p>`:''}</details></article>`;}
function connections(r){return edges.filter(e=>e.a===r.id||e.b===r.id).filter(e=>enabled.has(rows.find(n=>n.id===(e.a===r.id?e.b:e.a)).category));}
function graph(r){const links=connections(r),unique=[...new Set(links.map(e=>e.a===r.id?e.b:e.a))],chunks=Math.max(1,Math.ceil(unique.length/6));page=Math.min(page,chunks-1);const neighbors=unique.slice(page*6,page*6+6).map(x=>rows.find(n=>n.id===x));let svg='';neighbors.forEach((n,i)=>{const angle=i*Math.PI*2/Math.max(neighbors.length,1)-Math.PI/2,x=450+Math.cos(angle)*285,y=310+Math.sin(angle)*215;svg+=`<path d="M450 310 L${x} ${y}" stroke="#565a60" stroke-width="1.5"/>${node(n,x,y)}`;});return `<p class="caption">${h(r.name)} · ${unique.length} connected records. Select a node to follow its connections.</p><div class="mindmap-scroll"><svg class="mindmap" viewBox="0 0 900 620" role="group" aria-label="Connections to ${h(r.name)}">${svg}${node(r,450,310,true)}</svg></div>${chunks>1?`<div class="connections"><button id="graph-prev" ${page===0?'disabled':''}> Previous</button><span>${page+1} / ${chunks}</span><button id="graph-next" ${page===chunks-1?'disabled':''}>Next </button></div>`:''}<div class="graph-evidence">${links.filter(e=>neighbors.some(n=>n.id===(e.a===r.id?e.b:e.a))).map(e=>{const n=rows.find(n=>n.id===(e.a===r.id?e.b:e.a));return `<div><button data-node="${n.id}">${h(n.name)}</button><span>${h(e.label)} · ${h(e.date??'undated')}</span><a href="${h(e.url)}" target="_blank" rel="noopener">Evidence </a><small>${h(e.status)}</small></div>`;}).join('')||'<p>No reviewed connections match the active filters. Broaden the filters; no links are inferred from shared names or geography.</p>'}</div>`;}
